import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    g = [int(x) for x in data[1:1 + n * n]]
    MOD = 10 ** 9 + 7
    V = 100000
    spf = list(range(V + 1))
    i = 2
    while i * i <= V:
        if spf[i] == i:
            for j in range(i * i, V + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    cache = {}

    def divisors(x):
        d = cache.get(x)
        if d is None:
            d = [1]
            y = x
            while y > 1:
                p = spf[y]
                c = 0
                while y % p == 0:
                    y //= p
                    c += 1
                cur = d
                d = []
                m = 1
                for _ in range(c + 1):
                    for q in cur:
                        d.append(q * m)
                    m *= p
            cache[x] = d
        return d

    comp = [-1] * (n * n)
    regions = []
    blocked = 0
    for s in range(n * n):
        if g[s] == -1:
            blocked += 1
            continue
        if comp[s] != -1:
            continue
        cid = len(regions)
        cnt = {}
        comp[s] = cid
        stack = [s]
        while stack:
            u = stack.pop()
            v = g[u]
            cnt[v] = cnt.get(v, 0) + 1
            r, c = divmod(u, n)
            if r > 0 and comp[u - n] == -1 and g[u - n] != -1:
                comp[u - n] = cid
                stack.append(u - n)
            if r < n - 1 and comp[u + n] == -1 and g[u + n] != -1:
                comp[u + n] = cid
                stack.append(u + n)
            if c > 0 and comp[u - 1] == -1 and g[u - 1] != -1:
                comp[u - 1] = cid
                stack.append(u - 1)
            if c < n - 1 and comp[u + 1] == -1 and g[u + 1] != -1:
                comp[u + 1] = cid
                stack.append(u + 1)
        regions.append(cnt)
    G = {}
    for cnt in regions:
        for x, k in cnt.items():
            for d in divisors(x):
                G[d] = G.get(d, 0) + x * k
    total = 0
    for cnt in regions:
        C = {}
        for x, k in cnt.items():
            for d in divisors(x):
                C[d] = C.get(d, 0) + x * k
        for x, k in cnt.items():
            total += k * (G[x] - C[x])
    total -= blocked
    print(total % MOD)

